# Build demo grids from the exact marker locations supplied.
def make_grid(n, cell_h, cell_w, marks):
    h=n*cell_h+(n-1); w=n*cell_w+(n-1)
    g=[[0]*w for _ in range(h)]
    for r in range(n-1):
        for c in range(w): g[r*(cell_h+1)+cell_h][c]=8
    for c in range(n-1):
        for r in range(h): g[r][c*(cell_w+1)+cell_w]=8
    for color, pts in marks.items():
        for rr,cc in pts:
            g[rr*(cell_h+1)+cell_h//2][cc*(cell_w+1)+cell_w//2]=color
    return g

def expected_from_cells(n, cell_h, cell_w, marks):
    g=make_grid(n,cell_h,cell_w,marks)
    cells={}
    for color, pts in marks.items():
        for i,(r1,c1) in enumerate(pts):
            for r2,c2 in pts[i+1:]:
                if r1==r2: path=((r1,c) for c in range(min(c1,c2),max(c1,c2)+1))
                elif c1==c2: path=((r,c1) for r in range(min(r1,r2),max(r1,r2)+1))
                else: continue
                for p in path: cells.setdefault(p,set()).add(color)
    for (ri,ci), colors in cells.items():
        v=next(iter(colors)) if len(colors)==1 else 6
        for r in range(ri*(cell_h+1),ri*(cell_h+1)+cell_h):
            for c in range(ci*(cell_w+1),ci*(cell_w+1)+cell_w): g[r][c]=v
    return g

